<script lang="ts">
 import Help from './Help.svelte';
 import type {Snippet} from 'svelte';
 import {money} from './api';
 let {categoryFilter,timing}:{categoryFilter:Snippet<[string]>;timing:{basis?:string;count:number;unknownCount:number;totals:Record<string,string>;hours:{day:string;hour:number;donationCount:number;donationTotals:Record<string,string>}[]}}=$props();
 let dimension=$state('weekday'),metric=$state('count'),currency=$state('RUB');
 const currencies=$derived(Object.keys(timing.totals).sort());
 const activeCurrency=$derived(currencies.includes(currency)?currency:currencies[0]??'RUB');
 const rows=$derived((dimension==='weekday'?['пн','вт','ср','чт','пт','сб','вс']:Array.from({length:24},(_,i)=>String(i))).map(key=>{const cells=timing.hours.filter(c=>dimension==='weekday'?c.day===key:String(c.hour)===key);return {label:dimension==='weekday'?key:`${key.padStart(2,'0')}:00`,count:cells.reduce((n,c)=>n+c.donationCount,0),amount:cells.reduce((n,c)=>n+BigInt(c.donationTotals[activeCurrency]??'0'),0n)};}));
 const maximum=$derived(Math.max(1,...rows.map(r=>metric==='count'?r.count:Number(r.amount))));
</script>
<section class="panel donation-patterns"><header><h2>Когда приходят донаты</h2><span class="small muted">{timing.count} донатов</span><Help id="donation-timing-help" label="О времени донатов" text={`${timing.basis??'Все донаты выбранного периода, включая поступившие вне эфира.'} Это распределение фактов, а не рекомендация выбирать время стрима. У ${timing.unknownCount} донатов время неизвестно; они входят в итог, но не в график.`}/></header>{@render categoryFilter("Категория донатов")} <details class="controls"><summary>Настроить график</summary><div class="control-grid"><label>Группировать донаты<select aria-label="Группировать донаты" bind:value={dimension}><option value="weekday">Дни недели</option><option value="hour">Часы суток</option></select></label><label>Показатель донатов<select aria-label="Показатель донатов" bind:value={metric}><option value="count">Количество</option><option value="amount">Общая сумма</option></select></label>{#if metric==='amount'}<label>Валюта донатов<select aria-label="Валюта донатов" bind:value={currency}>{#each currencies as c}<option value={c}>{c}</option>{:else}<option value="RUB">RUB</option>{/each}</select></label>{/if}</div></details>
 <p class="small muted pattern-note">{metric==='count'?'Количество донатов':`Общая сумма · ${activeCurrency}`}</p>
 <div class="bars">{#each rows as r}<div class="bar-row"><span>{r.label}</span><div class="track"><i style:width={`${(metric==='count'?r.count:Number(r.amount))/maximum*100}%`}></i></div><strong>{metric==='count'?r.count:money(String(r.amount),activeCurrency)}</strong></div>{/each}</div>
</section>
<style>.controls{display:flex;flex-wrap:wrap;gap:12px;padding:16px 20px}label{display:grid;gap:6px;font-size:12px;flex:1 1 160px}select{width:100%;min-width:0}.bars{padding:4px 20px 16px;display:grid;gap:10px}.bar-row{display:grid;grid-template-columns:48px minmax(20px,1fr) 120px;align-items:center;gap:10px;font-size:12px}.bar-row strong{text-align:right;overflow-wrap:anywhere}.track{height:8px;background:#242a34;border-radius:4px;overflow:hidden}.track i{display:block;height:100%;background:var(--teal)}.pattern-note{padding:0 20px;margin:0 0 8px}@media(max-width:480px){.bar-row{grid-template-columns:40px minmax(20px,1fr) 100px}}</style>
